/** UC-002: View Veterinarians, with rows fetched as the visitor scrolls. */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VetsView extends VerticalLayout {

    private static final Logger LOGGER = LoggerFactory.getLogger(VetsView.class);
    private final transient VetRepository repository;

    public VetsView(VetRepository repository) {
        this.repository = repository;
        setSizeFull();

        Grid<Vet> grid = new Grid<>();
        grid.addColumn(Vet::firstName).setHeader("First Name");
        grid.addColumn(Vet::lastName).setHeader("Last Name");
        grid.addColumn(vet -> vet.specialties().isEmpty()
                ? "none" : String.join(", ", vet.specialties())).setHeader("Specialties");
        grid.setSizeFull();
        grid.setItems(query -> fetch(query.getOffset(), query.getLimit()), query -> count());
        add(new H2("Veterinarians"), grid);
        expand(grid);
    }

    private Stream<Vet> fetch(int offset, int limit) {
        try {
            return repository.findPage(offset, limit);
        } catch (DataAccessException exception) {
            showError(exception);
            return Stream.empty();
        }
    }

    private int count() {
        try {
            return repository.count();
        } catch (DataAccessException exception) {
            showError(exception);
            return 0;
        }
    }

    // Data-provider callbacks run after navigation, so route their failures
    // through the same error renderer used for navigation exceptions.
    private void showError(DataAccessException exception) {
        LOGGER.error("Unable to load veterinarians", exception);
        UI ui = UI.getCurrent();
        NavigationState state = new NavigationState(ui.getInternals().getRouter());
        state.setNavigationTarget(ApplicationErrorView.class);
        new ErrorStateRenderer(state).handle(new ErrorNavigationEvent(
                ui.getInternals().getRouter(), ui.getInternals().getActiveViewLocation(),
                ui, NavigationTrigger.PROGRAMMATIC,
                new ErrorParameter<>(Exception.class, exception, "Unable to load veterinarians.")));
    }
}
