+
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = {"BR-002", "BR-003"})
+    void navigationOpensAnonymousDirectoryWithNamesAndOrderedSpecialties() {
+        navigate(WelcomeView.class);
+        SideNavItem link = assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected Veterinarians navigation link");
+        UI.getCurrent().navigate(link.getPath());
+
+        Grid<Vet> grid = grid();
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertEquals(6, test(grid).size());
+        assertEquals("James", test(grid).getCellText(0, 0));
+        assertEquals("Carter", test(grid).getCellText(0, 1));
+        assertEquals("none", test(grid).getCellText(0, 2));
+        assertEquals("Linda", test(grid).getCellText(1, 0));
+        assertEquals("dentistry, surgery", test(grid).getCellText(1, 2));
+        assertEquals("radiology", test(grid).getCellText(3, 2));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryStillRendersGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(grid()).size());
+        assertDoesNotThrow(() -> find(H2.class).withText("Veterinarians").single(),
+                "Expected directory heading even without veterinarians");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void dataProviderFetchesBoundedNonOverlappingChunks() {
+        for (int i = 0; i < 120; i++) {
+            dsl.insertInto(VETS, VETS.FIRST_NAME, VETS.LAST_NAME)
+                    .values("Test", "Vet%03d".formatted(i)).execute();
+        }
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        assertFalse(grid.getDataProvider().isInMemory());
+        assertEquals(126, test(grid).size());
+
+        List<Vet> first = fetch(grid, 0, 50);
+        List<Vet> second = fetch(grid, 50, 50);
+        List<Vet> last = fetch(grid, 100, 50);
+        assertEquals(50, first.size());
+        assertEquals(50, second.size());
+        assertEquals(26, last.size());
+        assertEquals(126, Stream.of(first, second, last).flatMap(List::stream).map(Vet::id).distinct().count());
+        assertTrue(fetch(grid, 126, 50).isEmpty());
+        assertEquals(first, fetch(grid, 0, 50));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void fetchFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.dropTable(VET_SPECIALTIES).execute();
+
+        assertTrue(fetch(grid, 0, 50).isEmpty());
+
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+        assertDoesNotThrow(() -> find(H2.class).withText("Something happened...").single(),
+                "Expected application error view");
+        assertDoesNotThrow(() -> find(Paragraph.class).withText("Unable to load veterinarians.").single(),
+                "Expected a readable error without database details");
+        assertDoesNotThrow(() -> find(SideNavItem.class)
+                .withPropertyValue(SideNavItem::getLabel, "Home").single(),
+                "Expected navigation to remain available after failure");
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void countFailureReplacesDirectoryWithApplicationErrorView() {
+        navigate(VetsView.class);
+        Grid<Vet> grid = grid();
+        dsl.dropTable(VETS).cascade().execute();
+
+        assertEquals(0, grid.getDataProvider().size(new Query<>()));
+
+        assertTrue(find(Grid.class).all().isEmpty(), "Failed directory must not remain visible");
+        assertDoesNotThrow(() -> find(H2.class).withText("Something happened...").single(),
+                "Expected application error view");
+    }
+
+    private List<Vet> fetch(Grid<Vet> grid, int offset, int limit) {
+        return grid.getDataProvider().fetch(new Query<>(offset, limit, List.of(), null, null)).toList();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Vet> grid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected veterinarians grid");
+    }
+}
